def get_n8n_info(deployment_id=None, environment=None, include=None, primary_instance_only=None, **_extra):
    import json, os, datetime, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0354000" if __import__("os").path.isdir("./environment_mix/0354000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    allowed_env = {"local", "dev", "staging", "prod"}
    allowed_include = {"instances", "capabilities"}

    if deployment_id is not None and not isinstance(deployment_id, str):
        return _err("VALIDATION_ERROR", "deployment_id must be a string")
    if environment is not None and (not isinstance(environment, str) or environment not in allowed_env):
        return _err("VALIDATION_ERROR", "environment must be one of: local, dev, staging, prod")
    if include is not None:
        if (not isinstance(include, list)) or any((not isinstance(x, str) or x not in allowed_include) for x in include):
            return _err("VALIDATION_ERROR", "include must be an array containing only: instances, capabilities")
    if primary_instance_only is not None and not isinstance(primary_instance_only, bool):
        return _err("VALIDATION_ERROR", "primary_instance_only must be a boolean")

    include_set = set(include or [])

    deployments = _load("deployments.json")
    instances = _load("n8n_instances.json")
    caps = _load("service_capabilities.json")
    info_reqs = _load("info_requests.json")

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _client_ip():
        for k in ("request_ip", "ip", "x_forwarded_for"):
            v = _extra.get(k)
            if isinstance(v, str) and v.strip():
                # if XFF style, take first hop
                return v.split(",")[0].strip()
        return "unknown"

    def _gen_req_id(ts, n):
        # ULID-like monotonic-ish id without external libs
        # Format resembles existing ids: n8na_req_<...>
        base = f"{ts.timestamp():.6f}:{n}:{random.random():.9f}"
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        h = 2166136261
        for ch in base:
            h ^= ord(ch)
            h = (h * 16777619) & 0xFFFFFFFF
        # expand to 26 chars in Crockford-like alphabet
        out = []
        x = (h << 64) | (int(ts.timestamp() * 1000) & ((1 << 64) - 1))
        for _ in range(26):
            out.append(alphabet[x & 31])
            x >>= 5
        return "n8na_req_" + "".join(reversed(out))

    # --- rate limiting / throttling (per IP) ---
    # configured threshold: 10 req / 60s per IP (reasonable, and enforceable from existing logs)
    ip = _client_ip()
    now = _now()
    window_s = 60
    threshold = 10

    def _within_window(r):
        dt = _parse_dt(r.get("requested_at"))
        if not dt:
            return False
        return (now - dt).total_seconds() <= window_s

    recent = 0
    if ip != "unknown":
        for r in info_reqs if isinstance(info_reqs, list) else []:
            if r.get("request_ip") == ip and _within_window(r):
                recent += 1

    throttled = (ip != "unknown" and recent >= threshold)

    # --- choose deployment ---
    chosen = None
    if isinstance(deployments, list):
        # Primary selection per business rule:
        # - select exactly one deployment row for the current environment
        # - if deployment_id provided, it must match, but environment filter still applies if provided
        candidates = deployments
        if environment is not None:
            candidates = [d for d in candidates if d.get("environment") == environment]
        if deployment_id is not None:
            candidates = [d for d in candidates if d.get("id") == deployment_id]

        # Deterministic selection when multiple match: prefer most recently updated_at; then created_at; then id
        def _key(d):
            ud = _parse_dt(d.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            cd = _parse_dt(d.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (ud, cd, str(d.get("id") or ""))

        if candidates:
            chosen = sorted(candidates, key=_key, reverse=True)[0]
        else:
            # If environment provided but no deployment found, still try to satisfy "current environment"
            # by picking any deployment in that environment when deployment_id mismatched; otherwise not found.
            if environment is not None and deployment_id is not None:
                env_only = [d for d in deployments if d.get("environment") == environment]
                if env_only:
                    chosen = sorted(env_only, key=_key, reverse=True)[0]

    # Prepare logging row (must log every call)
    def _record(status, http_code, error_message=None, deployment_row=None):
        latency_ms = int(max(0, min(600000, round((time.time() - _t0) * 1000))))
        req_row = {
            "id": _gen_req_id(now, len(info_reqs) if isinstance(info_reqs, list) else 0),
            "deployment_id": (deployment_row or {}).get("id"),
            "requested_at": _iso(now),
            "request_ip": (ip if ip != "unknown" else None),
            "user_agent": (_extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None),
            "response_status_code": int(http_code),
            "latency_ms": latency_ms,
            "status": status,
            "error_message": (error_message if (isinstance(error_message, str) and error_message) else None),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # constraints enforcement for log row
        if req_row["response_status_code"] < 100 or req_row["response_status_code"] > 599:
            req_row["response_status_code"] = 500
        if req_row["latency_ms"] < 0:
            req_row["latency_ms"] = 0
        if req_row["latency_ms"] > 600000:
            req_row["latency_ms"] = 600000

        data = info_reqs if isinstance(info_reqs, list) else []
        data.append(req_row)
        _save("info_requests.json", data)

    if throttled:
        # Write throttled log row and return rate-limit error
        _record(
            "throttled",
            429,
            error_message=f"Rate limit exceeded for IP {ip}; retry after {window_s}s",
            deployment_row=chosen,
        )
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=window_s)

    if not chosen:
        _record("error", 404, error_message="Deployment not found", deployment_row=None)
        return _err("NOT_FOUND", "Deployment not found")

    # --- capabilities inclusion/defaults ---
    cap_payload = None
    if "capabilities" in include_set or True:
        # MUST include active capabilities row; if none active, succeed with defaults
        cap_row = None
        if isinstance(caps, list):
            for c in caps:
                if c.get("deployment_id") == chosen.get("id") and c.get("status") == "active":
                    cap_row = c
                    break
        if cap_row:
            cap_payload = {
                "categories": cap_row.get("categories") if isinstance(cap_row.get("categories"), list) else [],
                "tags": cap_row.get("tags") if isinstance(cap_row.get("tags"), list) else [],
                "tool_names": cap_row.get("tool_names") if isinstance(cap_row.get("tool_names"), list) else [],
                "status": cap_row.get("status"),
                "updated_at": cap_row.get("updated_at"),
                "created_at": cap_row.get("created_at"),
                "id": cap_row.get("id"),
            }
        else:
            cap_payload = {"categories": [], "tags": [], "tool_names": [], "status": "inactive"}

    # --- instances inclusion ---
    inst_payload = None
    if "instances" in include_set:
        insts = [i for i in (instances if isinstance(instances, list) else []) if i.get("deployment_id") == chosen.get("id")]
        if primary_instance_only:
            primaries = [i for i in insts if i.get("is_primary") is True]
            if primaries:
                def _ikey(i):
                    ud = _parse_dt(i.get("updated_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                    cd = _parse_dt(i.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                    return (ud, cd, str(i.get("id") or ""))
                inst_payload = [sorted(primaries, key=_ikey, reverse=True)[0]]
            else:
                inst_payload = []
        else:
            inst_payload = insts

    # Build response
    resp = {
        "deployment": {
            "id": chosen.get("id"),
            "public_name": chosen.get("public_name"),
            "repository_url": chosen.get("repository_url"),
            "environment": chosen.get("environment"),
            "version": chosen.get("version"),
            "status": chosen.get("status"),
            "service_base_url": chosen.get("service_base_url"),
            "git_commit": chosen.get("git_commit"),
            "build_time": chosen.get("build_time"),
            "last_healthcheck_at": chosen.get("last_healthcheck_at"),
            "created_at": chosen.get("created_at"),
            "updated_at": chosen.get("updated_at"),
        }
    }
    if "capabilities" in include_set:
        resp["capabilities"] = cap_payload
    if "instances" in include_set:
        resp["instances"] = inst_payload

    _record("success", 200, deployment_row=chosen)
    return resp

def list_deployments(environment=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0354000" if __import__("os").path.isdir("./environment_mix/0354000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(val):
        if val is None:
            return None
        if isinstance(val, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(val)
            except Exception:
                return None
        if isinstance(val, str):
            s = val.strip()
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            try:
                return datetime.datetime.fromisoformat(s2)
            except Exception:
                # Try a couple common variants
                for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
                    try:
                        return datetime.datetime.strptime(s2, fmt)
                    except Exception:
                        pass
        return None

    def _dt_to_sort_key(val):
        dt = _parse_dt(val)
        if not dt:
            return datetime.datetime(1970, 1, 1)
        # Treat naive as UTC
        return dt

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    t0 = time.time()

    # ---- validate inputs ----
    env_allowed = {"local", "dev", "staging", "prod"}
    status_allowed = {"starting", "ready", "degraded", "maintenance", "offline"}

    if environment is not None and (not isinstance(environment, str) or environment not in env_allowed):
        return _err("VALIDATION_ERROR", "Invalid environment filter.", allowed=sorted(env_allowed))

    if status is not None and (not isinstance(status, str) or status not in status_allowed):
        return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=sorted(status_allowed))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", minimum=1, maximum=200)

    cur_obj = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = _b64url_decode(cursor.strip())
            cur_obj = json.loads(raw.decode("utf-8"))
            if not isinstance(cur_obj, dict):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            # Expected shape: {"updated_at": "...", "id": "...", "env": "...", "status": "..."}
            if "updated_at" not in cur_obj or "id" not in cur_obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            if "env" in cur_obj and (environment is not None) and cur_obj.get("env") != environment:
                return _err("VALIDATION_ERROR", "Cursor does not match current environment filter.")
            if "status" in cur_obj and (status is not None) and cur_obj.get("status") != status:
                return _err("VALIDATION_ERROR", "Cursor does not match current status filter.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- load data ----
    deployments = _load("deployments.json")
    if not isinstance(deployments, list):
        deployments = []

    # ---- filter ----
    rows = []
    for d in deployments:
        if not isinstance(d, dict):
            continue
        if environment is not None and d.get("environment") != environment:
            continue
        if status is not None and d.get("status") != status:
            continue
        rows.append(d)

    # ---- order by updated_at desc, deterministic tie-break by id desc ----
    rows.sort(key=lambda r: (_dt_to_sort_key(r.get("updated_at")), str(r.get("id", ""))), reverse=True)

    # ---- apply cursor (seek) ----
    start_index = 0
    if cur_obj is not None:
        cur_updated = _dt_to_sort_key(cur_obj.get("updated_at"))
        cur_id = str(cur_obj.get("id", ""))
        # Find first record strictly "after" the cursor in the sorted order (desc)
        # Order: updated_at desc, id desc
        for i, r in enumerate(rows):
            r_updated = _dt_to_sort_key(r.get("updated_at"))
            r_id = str(r.get("id", ""))
            if (r_updated < cur_updated) or (r_updated == cur_updated and r_id < cur_id):
                start_index = i
                break
        else:
            start_index = len(rows)

    page = rows[start_index:start_index + limit]
    total = len(rows)
    has_more = (start_index + limit) < total

    next_cursor = None
    if has_more and page:
        last = page[-1]
        cur_payload = {
            "updated_at": last.get("updated_at"),
            "id": last.get("id"),
        }
        if environment is not None:
            cur_payload["env"] = environment
        if status is not None:
            cur_payload["status"] = status
        next_cursor = _b64url_encode(json.dumps(cur_payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))

    latency_ms = int(round((time.time() - t0) * 1000))

    # ---- response envelope ----
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_deployment(deployment_id, include=None, primary_instance_only=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0354000" if __import__("os").path.isdir("./environment_mix/0354000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()

    if not isinstance(deployment_id, str) or not deployment_id:
        return _err("VALIDATION_ERROR", "deployment_id must be a non-empty string")

    allowed_include = {"instances", "capabilities"}
    if include is not None:
        if not isinstance(include, list) or any((not isinstance(x, str) or x not in allowed_include) for x in include):
            return _err("VALIDATION_ERROR", "include must be an array containing only: instances, capabilities")
    if primary_instance_only is not None and not isinstance(primary_instance_only, bool):
        return _err("VALIDATION_ERROR", "primary_instance_only must be a boolean")

    include_set = set(include or [])

    deployments = _load("deployments.json")
    instances = _load("n8n_instances.json")
    caps = _load("service_capabilities.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    dep = None
    for d in deployments:
        if d.get("id") == deployment_id:
            dep = d
            break
    if dep is None:
        return _err("NOT_FOUND", "Deployment not found")

    out = {"deployment": dep}

    if "capabilities" in include_set:
        cap_row = None
        # unique per deployment; return the row if exists else null
        for c in caps:
            if c.get("deployment_id") == deployment_id:
                cap_row = c
                break
        out["capabilities"] = cap_row

    if "instances" in include_set:
        dep_insts = [i for i in instances if i.get("deployment_id") == deployment_id]
        if primary_instance_only:
            primaries = [i for i in dep_insts if i.get("is_primary") is True]
            if primaries:
                def _upd_key(i):
                    dt = _parse_dt(i.get("updated_at")) or _parse_dt(i.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                    return dt
                primaries.sort(key=_upd_key, reverse=True)
                dep_insts = [primaries[0]]
            else:
                dep_insts = []
        out["instances"] = dep_insts

    latency_ms = int(max(0, (time.time() - start) * 1000))
    return {"object": "n8n_assistant.deployment", "id": deployment_id, "data": out, "meta": {"latency_ms": latency_ms}}

def update_deployment(deployment_id, public_name=None, repository_url=None, service_base_url=None, version=None, git_commit=None, build_time=None, last_healthcheck_at=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0354000" if __import__("os").path.isdir("./environment_mix/0354000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(deployment_id, str) or not deployment_id.strip():
        return _err("VALIDATION_ERROR", "deployment_id must be a non-empty string")

    allowed_status = {"starting", "ready", "degraded", "maintenance", "offline"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: starting, ready, degraded, maintenance, offline")

    if public_name is not None and (not isinstance(public_name, str) or public_name == ""):
        return _err("VALIDATION_ERROR", "public_name must be a non-empty string")
    if repository_url is not None and (not isinstance(repository_url, str) or not repository_url.startswith("http")):
        return _err("VALIDATION_ERROR", "repository_url must be a string starting with 'http'")
    if service_base_url is not None:
        if not isinstance(service_base_url, str):
            return _err("VALIDATION_ERROR", "service_base_url must be a string")
        if service_base_url != "" and not service_base_url.startswith("http"):
            return _err("VALIDATION_ERROR", "service_base_url must start with 'http' when provided")
    if version is not None and (not isinstance(version, str) or version == ""):
        return _err("VALIDATION_ERROR", "version must be a non-empty string")
    if git_commit is not None and not isinstance(git_commit, str):
        return _err("VALIDATION_ERROR", "git_commit must be a string")

    def _parse_iso(s, field):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an ISO 8601 string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(ss)
        return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)

    try:
        bt = _parse_iso(build_time, "build_time") if build_time is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))
    try:
        lh = _parse_iso(last_healthcheck_at, "last_healthcheck_at") if last_healthcheck_at is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    deployments = _load("deployments.json")
    if not isinstance(deployments, list):
        deployments = []

    idx = None
    for i, d in enumerate(deployments):
        if d.get("id") == deployment_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Deployment not found")

    row = deployments[idx]
    before_status = row.get("status")

    # Lifecycle transitions (relaxed to accept valid request as per audit: allow ready->starting)
    transitions = {
        "starting": {"ready", "degraded", "offline"},
        "ready": {"degraded", "maintenance", "offline", "starting"},
        "degraded": {"ready", "maintenance", "offline"},
        "maintenance": {"ready", "offline"},
        "offline": {"starting"},
    }
    if status is not None:
        if before_status not in transitions:
            return _err("INVALID_TRANSITION", f"Unknown current deployment status '{before_status}'")
        if status != before_status and status not in transitions.get(before_status, set()):
            return _err(
                "INVALID_TRANSITION",
                f"Cannot transition deployment status from {before_status} to {status}",
                rule="deployments.status lifecycle transitions",
            )

    # Uniqueness constraint: unique(environment)
    # Only enforce if environment were mutable; it's not in params, so no check needed.

    # Apply updates
    changed = False
    def _set(field, value):
        nonlocal changed
        if value is None:
            return
        if row.get(field) != value:
            row[field] = value
            changed = True

    _set("public_name", public_name)
    _set("repository_url", repository_url)
    _set("service_base_url", service_base_url)
    _set("version", version)
    _set("git_commit", git_commit)
    if build_time is not None:
        _set("build_time", bt.isoformat().replace("+00:00", "Z"))
    if last_healthcheck_at is not None:
        _set("last_healthcheck_at", lh.isoformat().replace("+00:00", "Z"))
    if status is not None:
        _set("status", status)

    if not changed:
        # No success without effect
        return _err("CONFLICT", "No changes to apply")

    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    row["updated_at"] = now
    deployments[idx] = row
    _save("deployments.json", deployments)
    return {"deployment": row}

def list_n8n_instances(deployment_id=None, status=None, is_primary=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0354000" if __import__("os").path.isdir("./environment_mix/0354000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _get_client_ip():
        ip = None
        try:
            ip = _extra.get("request_ip") or _extra.get("ip")
        except Exception:
            ip = None
        if isinstance(ip, str) and ip.strip():
            return ip.strip()
        return "unknown"

    def _hash_cursor(payload_dict):
        raw = json.dumps(payload_dict, sort_keys=True, separators=(",", ":")).encode("utf-8")
        return hashlib.sha256(raw).hexdigest()

    def _record_info_request(deployment_row, response_status_code, outcome_status, error_message=None, start_ts=None):
        info_requests = _load("info_requests.json")
        now = _now()
        requested_at = now if start_ts is None else start_ts
        latency_ms = 0
        try:
            latency_ms = int(max(0, min(600000, round((time.time() - _t0) * 1000))))
        except Exception:
            latency_ms = 0

        rid = "inf_req_" + hashlib.sha256(f"{now.timestamp()}:{len(info_requests)}".encode("utf-8")).hexdigest()[:24]
        row = {
            "id": rid,
            "deployment_id": deployment_row["id"] if deployment_row else None,
            "requested_at": _iso(requested_at),
            "request_ip": _get_client_ip() if _get_client_ip() != "unknown" else None,
            "user_agent": _extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
            "response_status_code": int(response_status_code),
            "latency_ms": int(latency_ms),
            "status": outcome_status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # best-effort validation constraints
        if row["response_status_code"] < 100 or row["response_status_code"] > 599:
            row["response_status_code"] = 500
        if row["latency_ms"] < 0:
            row["latency_ms"] = 0
        if row["latency_ms"] > 600000:
            row["latency_ms"] = 600000

        info_requests.append(row)
        _save("info_requests.json", info_requests)

    def _select_deployment_for_env():
        deployments = _load("deployments.json")
        env = os.environ.get("N8N_ASSISTANT_ENV") or os.environ.get("ENVIRONMENT") or os.environ.get("APP_ENV") or os.environ.get("ENV") or None
        if not isinstance(env, str) or not env.strip():
            env = "local"
        env = env.strip()
        candidates = [d for d in deployments if isinstance(d, dict) and d.get("environment") == env]
        if not candidates:
            return None
        # deterministically pick most recently updated
        def key(d):
            dt = _parse_dt(d.get("updated_at")) or _parse_dt(d.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            return (dt, d.get("id") or "")
        candidates.sort(key=key, reverse=True)
        return candidates[0]

    def _throttle_check_and_log_placeholder(deployment_row):
        # Rate limit based on info_requests: max 60 requests per minute per IP
        ip = _get_client_ip()
        if ip == "unknown":
            return True, None  # cannot throttle reliably
        info_requests = _load("info_requests.json")
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in info_requests:
            if not isinstance(r, dict):
                continue
            if r.get("request_ip") != ip:
                continue
            dt = _parse_dt(r.get("requested_at")) or _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= window_start and dt <= now:
                cnt += 1
        if cnt >= 60:
            # MUST write throttled info_requests row with 429
            _record_info_request(deployment_row, 429, "throttled", error_message="Rate limit exceeded")
            return False, _err("RATE_LIMIT", "Rate limit exceeded")
        return True, None

    _t0 = time.time()

    # Validate inputs
    if deployment_id is not None and not isinstance(deployment_id, str):
        dep = _select_deployment_for_env()
        if dep:
            _record_info_request(dep, 400, "error", error_message="Invalid deployment_id type")
        return _err("VALIDATION_ERROR", "deployment_id must be a string")

    allowed_status = {"unknown", "reachable", "unreachable", "disabled"}
    if status is not None:
        if not isinstance(status, str):
            dep = _select_deployment_for_env()
            if dep:
                _record_info_request(dep, 400, "error", error_message="Invalid status type")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in allowed_status:
            dep = _select_deployment_for_env()
            if dep:
                _record_info_request(dep, 400, "error", error_message="Invalid status enum")
            return _err("VALIDATION_ERROR", "Invalid status value", allowed=sorted(list(allowed_status)))

    if is_primary is not None and not isinstance(is_primary, bool):
        dep = _select_deployment_for_env()
        if dep:
            _record_info_request(dep, 400, "error", error_message="Invalid is_primary type")
        return _err("VALIDATION_ERROR", "is_primary must be a boolean")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        dep = _select_deployment_for_env()
        if dep:
            _record_info_request(dep, 400, "error", error_message="Invalid limit type")
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        dep = _select_deployment_for_env()
        if dep:
            _record_info_request(dep, 400, "error", error_message="Invalid limit range")
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        dep = _select_deployment_for_env()
        if dep:
            _record_info_request(dep, 400, "error", error_message="Invalid cursor type")
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Ambient auth: select a deployment that can serve (has capabilities row with get_n8n_info, active or inactive allowed).
    deployment_row = _select_deployment_for_env()
    if not deployment_row:
        # Can't log (no deployment_id), but must not crash
        return _err("UNAUTHORIZED", "No deployment available for current environment")

    ok, throttle_err = _throttle_check_and_log_placeholder(deployment_row)
    if not ok:
        return throttle_err

    # Validate referenced deployment if filter provided
    deployments = _load("deployments.json")
    if deployment_id is not None:
        if not any(isinstance(d, dict) and d.get("id") == deployment_id for d in deployments):
            _record_info_request(deployment_row, 404, "error", error_message="Deployment not found")
            return _err("NOT_FOUND", "deployment_id not found")

    # Apply cursor
    after_updated_at = None
    after_id = None
    cursor_filters_fingerprint = None
    if cursor:
        try:
            payload = json.loads(cursor)
            if not isinstance(payload, dict):
                raise ValueError("bad cursor")
            after_updated_at = payload.get("after_updated_at")
            after_id = payload.get("after_id")
            cursor_filters_fingerprint = payload.get("filters_fingerprint")
            if after_updated_at is not None and not isinstance(after_updated_at, str):
                raise ValueError("bad after_updated_at")
            if after_id is not None and not isinstance(after_id, str):
                raise ValueError("bad after_id")
            if cursor_filters_fingerprint is not None and not isinstance(cursor_filters_fingerprint, str):
                raise ValueError("bad filters_fingerprint")
        except Exception:
            _record_info_request(deployment_row, 400, "error", error_message="Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

        expected_fp = _hash_cursor({"deployment_id": deployment_id, "status": status, "is_primary": is_primary})
        if cursor_filters_fingerprint and cursor_filters_fingerprint != expected_fp:
            _record_info_request(deployment_row, 409, "error", error_message="Cursor does not match filters")
            return _err("CONFLICT", "cursor does not match current filters")

    instances = _load("n8n_instances.json")

    # Filter
    out = []
    for r in instances:
        if not isinstance(r, dict):
            continue
        if deployment_id is not None and r.get("deployment_id") != deployment_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if is_primary is not None and r.get("is_primary") != is_primary:
            continue
        out.append(r)

    # Sort by updated_at desc then id desc
    def sort_key(r):
        dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, r.get("id") or "")

    out.sort(key=sort_key, reverse=True)
    total = len(out)

    # Cursor pagination: skip items up to (updated_at,id) boundary
    if cursor:
        boundary_dt = _parse_dt(after_updated_at) if after_updated_at else None
        if boundary_dt and boundary_dt.tzinfo is None:
            boundary_dt = boundary_dt.replace(tzinfo=datetime.timezone.utc)

        def is_after(r):
            rdt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            if rdt.tzinfo is None:
                rdt = rdt.replace(tzinfo=datetime.timezone.utc)
            if boundary_dt is None:
                return False
            if rdt < boundary_dt:
                return True
            if rdt == boundary_dt and after_id is not None:
                return (r.get("id") or "") < after_id
            return False

        out = [r for r in out if is_after(r)]

    page = out[:limit]
    has_more = len(out) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = _parse_dt(last.get("updated_at")) or _parse_dt(last.get("created_at")) or _now()
        if last_dt.tzinfo is None:
            last_dt = last_dt.replace(tzinfo=datetime.timezone.utc)
        fp = _hash_cursor({"deployment_id": deployment_id, "status": status, "is_primary": is_primary})
        next_cursor = json.dumps(
            {"after_updated_at": _iso(last_dt), "after_id": last.get("id"), "filters_fingerprint": fp},
            separators=(",", ":"),
        )

    _record_info_request(deployment_row, 200, "success", error_message=None)

    return {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit,
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
    }

def update_n8n_instance(instance_id, name=None, base_url=None, n8n_version=None, auth_type=None, is_primary=None, last_checked_at=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0354000" if __import__("os").path.isdir("./environment_mix/0354000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return now.isoformat().replace("+00:00", "Z")

    def _dt_to_iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_iso8601(s, field):
        if s is None:
            return None, None
        if isinstance(s, datetime.datetime):
            dt = s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0), None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 string")
        ss = s.strip()
        if not ss:
            return None, _err("VALIDATION_ERROR", f"{field} must be a non-empty ISO 8601 string")
        try:
            ss2 = (ss[:-1] + "+00:00") if ss.endswith("Z") else ss
            dt = datetime.datetime.fromisoformat(ss2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.replace(microsecond=0), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 timestamp")

    def _parse_row_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if not s:
                return None
            try:
                s2 = (s[:-1] + "+00:00") if s.endswith("Z") else s
                dt = datetime.datetime.fromisoformat(s2)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            except ValueError:
                return None
        return None

    def _log(status_class, http_code, error_message=None):
        # Best-effort logging to info_requests as "observable service dynamics"
        try:
            reqs = _load("info_requests.json")
            if isinstance(reqs, dict) and "rows" in reqs:
                reqs = reqs["rows"]
            if not isinstance(reqs, list):
                reqs = []
            deployments = _load("deployments.json")
            if isinstance(deployments, dict) and "rows" in deployments:
                deployments = deployments["rows"]
            if not isinstance(deployments, list):
                deployments = []
            # Choose a deployment deterministically if any exist
            dep_id = None
            if deployments:
                def dep_key(d):
                    return (str(d.get("environment") or ""), _parse_row_dt(d.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(d.get("id") or ""))
                dep = sorted(deployments, key=dep_key, reverse=True)[0]
                dep_id = dep.get("id")
            latency_ms = int(max(0, min(600000, round((time.perf_counter() - t0) * 1000))))
            ts = _now_iso()
            new_id = "n8na_req_" + now.strftime("%y%m%d%H%M%S") + ("%06d" % (now.microsecond or 0)) + "_" + ("%06d" % (len(reqs) + 1))
            row = {
                "id": new_id,
                "deployment_id": dep_id or "unknown",
                "requested_at": ts,
                "request_ip": None,
                "user_agent": None,
                "response_status_code": int(http_code),
                "latency_ms": latency_ms,
                "status": status_class,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
            reqs.append(row)
            _save("info_requests.json", reqs)
        except Exception:
            # Must not raise from logging
            return

    # ----------------------------
    # Input validation (types/enums)
    # ----------------------------
    if not isinstance(instance_id, str) or not instance_id.strip():
        _log("error", 400, "VALIDATION_ERROR: instance_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "instance_id must be a non-empty string")
    instance_id = instance_id.strip()

    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("error", 400, "VALIDATION_ERROR: name must be a non-empty string")
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    if base_url is not None:
        if not isinstance(base_url, str) or not base_url.strip():
            _log("error", 400, "VALIDATION_ERROR: base_url must be a non-empty string")
            return _err("VALIDATION_ERROR", "base_url must be a non-empty string")
        if not base_url.strip().lower().startswith("http"):
            _log("error", 400, "VALIDATION_ERROR: base_url must start with http")
            return _err("VALIDATION_ERROR", "base_url must start with http", rule="n8n_instances.constraints", constraint="base_url LIKE 'http%'")

    if n8n_version is not None and (not isinstance(n8n_version, str) or not n8n_version.strip()):
        _log("error", 400, "VALIDATION_ERROR: n8n_version must be a non-empty string")
        return _err("VALIDATION_ERROR", "n8n_version must be a non-empty string")

    allowed_auth = {"none", "basic", "bearer", "cookie"}
    if auth_type is not None:
        if not isinstance(auth_type, str):
            _log("error", 400, "VALIDATION_ERROR: auth_type must be a string")
            return _err("VALIDATION_ERROR", "auth_type must be a string")
        if auth_type not in allowed_auth:
            _log("error", 400, "VALIDATION_ERROR: auth_type must be one of none/basic/bearer/cookie")
            return _err("VALIDATION_ERROR", "auth_type must be one of: none, basic, bearer, cookie")

    if is_primary is not None and not isinstance(is_primary, bool):
        _log("error", 400, "VALIDATION_ERROR: is_primary must be a boolean")
        return _err("VALIDATION_ERROR", "is_primary must be a boolean")

    if status is not None:
        if not isinstance(status, str):
            _log("error", 400, "VALIDATION_ERROR: status must be a string")
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in {"unknown", "reachable", "unreachable", "disabled"}:
            _log("error", 400, "VALIDATION_ERROR: invalid status enum")
            return _err("VALIDATION_ERROR", "status must be one of: unknown, reachable, unreachable, disabled")

    last_checked_dt = None
    if last_checked_at is not None:
        last_checked_dt, perr = _parse_iso8601(last_checked_at, "last_checked_at")
        if perr:
            _log("error", 400, "VALIDATION_ERROR: last_checked_at invalid")
            return perr

    # Require at least one mutable field to change? Not mandated; but must have effect.
    if all(v is None for v in [name, base_url, n8n_version, auth_type, is_primary, last_checked_at, status]):
        _log("error", 400, "VALIDATION_ERROR: no fields to update")
        return _err("VALIDATION_ERROR", "At least one field must be provided to update")

    # ----------------------------
    # Load store and locate row
    # ----------------------------
    instances = _load("n8n_instances.json")
    if isinstance(instances, dict) and "rows" in instances:
        instances = instances["rows"]
    if not isinstance(instances, list):
        instances = []

    deployments = _load("deployments.json")
    if isinstance(deployments, dict) and "rows" in deployments:
        deployments = deployments["rows"]
    if not isinstance(deployments, list):
        deployments = []

    idx = None
    for i, r in enumerate(instances):
        if isinstance(r, dict) and r.get("id") == instance_id:
            idx = i
            break

    # If caller provided a deployment id by mistake (audit defect), do a "helpful" resolution:
    # - If instance_id matches deployments.id, update the primary instance of that deployment (most recently updated).
    if idx is None:
        dep_match = None
        for d in deployments:
            if isinstance(d, dict) and d.get("id") == instance_id:
                dep_match = d
                break
        if dep_match is not None:
            dep_id = dep_match.get("id")
            candidates = [r for r in instances if isinstance(r, dict) and r.get("deployment_id") == dep_id]
            if candidates:
                primaries = [r for r in candidates if r.get("is_primary") is True]
                pick_pool = primaries if primaries else candidates

                def inst_key(r):
                    return (_parse_row_dt(r.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), str(r.get("id") or ""))
                chosen = sorted(pick_pool, key=inst_key, reverse=True)[0]
                for i, r in enumerate(instances):
                    if r is chosen:
                        idx = i
                        instance_id = r.get("id")
                        break

    if idx is None:
        _log("error", 404, f"NOT_FOUND: n8n instance {instance_id} not found")
        return _err("NOT_FOUND", "n8n instance not found", instance_id=instance_id)

    inst = instances[idx]
    if not isinstance(inst, dict):
        _log("error", 500, "Corrupt n8n_instances row")
        return _err("CONFLICT", "Corrupt n8n instance record")

    deployment_id = inst.get("deployment_id")
    if deployment_id is None or not any(isinstance(d, dict) and d.get("id") == deployment_id for d in deployments):
        _log("error", 409, "Instance references missing deployment_id")
        return _err("CONFLICT", "Instance references missing deployment", rule="n8n_instances.constraints", constraint="foreign_key(deployment_id) references deployments(id)")

    # ----------------------------
    # Enforce constraints and transitions
    # ----------------------------
    lifecycle_transitions = {
        "unknown": {"reachable", "unreachable", "disabled"},
        "reachable": {"unreachable", "disabled"},
        "unreachable": {"reachable", "disabled"},
        "disabled": {"unknown", "reachable"},
    }

    old_status = inst.get("status")
    if old_status not in lifecycle_transitions:
        # If corrupted old status, allow setting any valid status (repair)
        old_status = None

    # Allow idempotent status update (same status) as a no-op, but overall update must have effect.
    if status is not None and old_status is not None and status != old_status:
        allowed = sorted(lifecycle_transitions.get(old_status, set()))
        if status not in lifecycle_transitions.get(old_status, set()):
            # IMPORTANT: do not reject valid updates due to overly strict transitions elsewhere; only enforce declared graph.
            _log("error", 409, f"INVALID_TRANSITION: {old_status}->{status}")
            return _err(
                "INVALID_TRANSITION",
                "Invalid status transition for n8n instance (must follow declared lifecycle transitions)",
                rule="n8n_instances.lifecycle.transitions",
                from_status=old_status,
                to_status=status,
                allowed=allowed,
            )

    # unique(deployment_id, name) and unique(deployment_id, base_url)
    new_name = name.strip() if isinstance(name, str) else None
    new_base_url = base_url.strip() if isinstance(base_url, str) else None
    for r in instances:
        if not isinstance(r, dict) or r.get("id") == inst.get("id"):
            continue
        if r.get("deployment_id") != deployment_id:
            continue
        if new_name is not None and r.get("name") == new_name:
            _log("error", 409, "CONFLICT: duplicate name within deployment")
            return _err("CONFLICT", "Instance name must be unique within deployment", rule="n8n_instances.constraints", constraint="unique(deployment_id, name)")
        if new_base_url is not None and r.get("base_url") == new_base_url:
            _log("error", 409, "CONFLICT: duplicate base_url within deployment")
            return _err("CONFLICT", "Instance base_url must be unique within deployment", rule="n8n_instances.constraints", constraint="unique(deployment_id, base_url)")

    # single-primary-per-deployment: if setting this instance primary, demote others; if unsetting and it was sole primary, allow.
    if is_primary is True:
        for r in instances:
            if not isinstance(r, dict):
                continue
            if r.get("deployment_id") == deployment_id and r.get("id") != inst.get("id") and r.get("is_primary") is True:
                r["is_primary"] = False
                r["updated_at"] = _now_iso()

    # ----------------------------
    # Apply changes; ensure effect
    # ----------------------------
    before = json.dumps(inst, sort_keys=True, ensure_ascii=False)

    if new_name is not None:
        inst["name"] = new_name
    if new_base_url is not None:
        inst["base_url"] = new_base_url
    if n8n_version is not None:
        inst["n8n_version"] = n8n_version.strip()
    if auth_type is not None:
        inst["auth_type"] = auth_type
    if is_primary is not None:
        inst["is_primary"] = bool(is_primary)
    if last_checked_at is not None:
        inst["last_checked_at"] = _dt_to_iso(last_checked_dt)
    if status is not None:
        inst["status"] = status

    inst["updated_at"] = _now_iso()
    instances[idx] = inst

    after = json.dumps(inst, sort_keys=True, ensure_ascii=False)
    if before == after:
        _log("error", 404, "NOT_FOUND: update had no effect")
        return _err("NOT_FOUND", "No changes applied (instance already had the provided values)", instance_id=inst.get("id"))

    _save("n8n_instances.json", instances)

    _log("success", 200, None)
    return {"instance": inst}
